#include <iostream>
#include <vector>
using namespace std;

const int MOD = 998244353;

long long mod_pow(long long a, long long k) {
    if (k == 0) return 1;
    long long p = mod_pow(a, k >> 1);
    p = p * p % MOD;
    if (k & 1) p = p * a % MOD;
    return p;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    long long k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << endl;
        return 0;
    }
    int c = n - (int)k;
    vector<int> ff(2 * n), gg(2 * n);
    for (int f = 1, i = 0; i < 2 * n; i++) {
        ff[i] = f;
        gg[i] = mod_pow(f, MOD - 2);
        f = (long long)f * (i + 1) % MOD;
    }
    auto ch = [&](int n, int k) {
        return (long long)ff[n] * gg[k] % MOD * gg[n - k] % MOD;
    };
    long long ans = 0;
    for (int a = 1; a <= c; a++) {
        long long x = mod_pow(a, n) * ch(c, a) % MOD;
        ans += ((c - a) % 2 == 0 ? x : -x);
    }
    ans %= MOD;
    if (ans < 0) ans += MOD;
    ans = ans * ch(n, c) % MOD;
    if (k > 0) ans = ans * 2 % MOD;
    cout << ans << endl;
    return 0;
}

